        if (x_final == 0) x_final = n;
        long y_final = (finalV[1] + 1) % n;
        if (y_final == 0) y_final = n;

        System.out.println(x_final + " " + y_final);
    }

    static long[][] matrixMultiply(long[][] A, long[][] B, long mod) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long sum = 0;
                for (int k = 0; k < n; k++) {
                    sum = (sum + A[i][k] * B[k][j]) % mod;
                }
                C[i][j] = sum;
            }
        }
        return C;
    }

    static long[][] matrixPower(long[][] M, long power, long mod) {
        int n = M.length;
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) {
            result[i][i] = 1;
        }

        while (power > 0) {
            if ((power & 1) == 1) {
                result = matrixMultiply(result, M, mod);
            }
            M = matrixMultiply(M, M, mod);
            power >>= 1;
        }
        return result;
    }
